import{_ as t,o as e,c as p,ag as l}from"./chunks/framework.i8sMDeRW.js";const u=JSON.parse('{"title":"第 5 课：参数、训练和推理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/12-llm-engineering/05-parameters-training-inference.md","filePath":"guide/12-llm-engineering/05-parameters-training-inference.md","lastUpdated":1782288443000}'),i={name:"guide/12-llm-engineering/05-parameters-training-inference.md"};function s(n,a,o,d,r,h){return e(),p("div",null,[...a[0]||(a[0]=[l(`<h1 id="第-5-课-参数、训练和推理" tabindex="-1">第 5 课：参数、训练和推理 <a class="header-anchor" href="#第-5-课-参数、训练和推理" aria-label="Permalink to &quot;第 5 课：参数、训练和推理&quot;">​</a></h1><blockquote><p>本课目标：理解模型里的“参数”是什么，训练和推理有什么区别，以及这些概念如何影响 AI 产品的成本、速度、质量和上线方案。</p></blockquote><hr><h2 id="_1-先说结论" tabindex="-1">1. 先说结论 <a class="header-anchor" href="#_1-先说结论" aria-label="Permalink to &quot;1. 先说结论&quot;">​</a></h2><p>LLM 里有很多很多<strong>参数</strong>。</p><p>简单说：</p><blockquote><p>参数是模型内部用来做判断的小数字。</p></blockquote><p>训练时，模型会不断调整这些数字。</p><p>推理时，模型会使用这些已经调好的数字来生成回答。</p><p>所以：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>训练 = 调整模型</span></span>
<span class="line"><span>推理 = 使用模型</span></span></code></pre></div><p>这是理解 LLM 工程的核心区别。</p><hr><h2 id="_2-什么是参数" tabindex="-1">2. 什么是参数？ <a class="header-anchor" href="#_2-什么是参数" aria-label="Permalink to &quot;2. 什么是参数？&quot;">​</a></h2><p>参数听起来很抽象。</p><p>你可以先把它想成：</p><blockquote><p>模型内部很多很多可以调节的小旋钮。</p></blockquote><p>模型不是靠一条条人工写好的规则工作。</p><p>它靠大量参数共同决定：</p><ul><li>哪个 token 更可能出现</li><li>哪些词之间有关联</li><li>哪种回答风格更合适</li><li>哪段上下文更重要</li><li>代码应该怎么补全</li><li>问题应该怎么回答</li></ul><p>比如模型看到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>中国的首都是</span></span></code></pre></div><p>它会通过参数计算出下一个 token 更可能是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>北京</span></span></code></pre></div><p>而不是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>香蕉</span></span></code></pre></div><hr><h2 id="_3-生活类比-调音台" tabindex="-1">3. 生活类比：调音台 <a class="header-anchor" href="#_3-生活类比-调音台" aria-label="Permalink to &quot;3. 生活类比：调音台&quot;">​</a></h2><p>想象一个调音师面前有一个巨大的调音台。</p><p>上面有很多旋钮：</p><ul><li>音量</li><li>低音</li><li>高音</li><li>混响</li><li>人声</li><li>鼓声</li><li>吉他声</li></ul><p>调音师不断调这些旋钮，让音乐听起来更好。</p><p>LLM 的参数也像这些旋钮。</p><p>训练模型时，就像不断调旋钮。</p><p>目标是让模型越来越会预测正确的下一个 token。</p><hr><h2 id="_4-参数越多越好吗" tabindex="-1">4. 参数越多越好吗？ <a class="header-anchor" href="#_4-参数越多越好吗" aria-label="Permalink to &quot;4. 参数越多越好吗？&quot;">​</a></h2><p>不一定。</p><p>参数多通常意味着模型容量更大。</p><p>“容量”可以理解成：</p><blockquote><p>模型能装下和表达更多复杂模式的能力。</p></blockquote><p>比如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1B 参数 = 10 亿参数</span></span>
<span class="line"><span>7B 参数 = 70 亿参数</span></span>
<span class="line"><span>70B 参数 = 700 亿参数</span></span></code></pre></div><p>大模型通常更强，尤其在：</p><ul><li>复杂推理</li><li>多语言理解</li><li>长文档处理</li><li>代码生成</li><li>多任务能力</li></ul><p>但大模型也通常：</p><ul><li>更慢</li><li>更贵</li><li>更吃显存</li><li>更难部署</li><li>推理成本更高</li></ul><p>所以工程上不是永远选最大模型。</p><p>产品上更常见的问题是：</p><blockquote><p>用多大的模型，刚好够解决当前任务？</p></blockquote><hr><h2 id="_5-小模型什么时候更好" tabindex="-1">5. 小模型什么时候更好？ <a class="header-anchor" href="#_5-小模型什么时候更好" aria-label="Permalink to &quot;5. 小模型什么时候更好？&quot;">​</a></h2><p>小模型在很多场景反而更合适。</p><p>比如：</p><ul><li>分类任务</li><li>简单客服问答</li><li>固定格式抽取</li><li>本地设备运行</li><li>高并发低成本场景</li><li>对响应速度要求很高的场景</li></ul><p>例如一个任务只是判断用户反馈是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>投诉 / 建议 / 咨询 / 表扬</span></span></code></pre></div><p>这不一定需要超大模型。</p><p>一个小模型或者传统机器学习方法可能已经够用。</p><p>产品经理要记住：</p><blockquote><p>模型选择不是炫技，而是成本、质量、速度和风险的平衡。</p></blockquote><hr><h2 id="_6-什么是训练" tabindex="-1">6. 什么是训练？ <a class="header-anchor" href="#_6-什么是训练" aria-label="Permalink to &quot;6. 什么是训练？&quot;">​</a></h2><p>训练就是：</p><blockquote><p>用大量数据调整模型参数，让模型更会预测下一个 token。</p></blockquote><p>训练过程可以粗略理解为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给模型一句话</span></span>
<span class="line"><span>→ 让它猜下一个 token</span></span>
<span class="line"><span>→ 看它猜得对不对</span></span>
<span class="line"><span>→ 如果错了，就调整参数</span></span>
<span class="line"><span>→ 重复很多很多次</span></span></code></pre></div><p>比如训练数据里有：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天空是蓝色的。</span></span></code></pre></div><p>模型看到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天空是</span></span></code></pre></div><p>它可能一开始猜错。</p><p>训练系统会告诉它：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正确答案更接近“蓝色”</span></span></code></pre></div><p>然后参数被微调一点点。</p><p>重复海量数据后，模型慢慢学到很多语言和知识模式。</p><hr><h2 id="_7-生活类比-练习考试" tabindex="-1">7. 生活类比：练习考试 <a class="header-anchor" href="#_7-生活类比-练习考试" aria-label="Permalink to &quot;7. 生活类比：练习考试&quot;">​</a></h2><p>训练模型像学生刷题。</p><p>学生做题：</p><ol><li>看题目</li><li>写答案</li><li>对答案</li><li>知道哪里错了</li><li>改进方法</li><li>继续做下一题</li></ol><p>模型训练也是类似。</p><p>只不过学生改的是自己的理解方法，模型改的是内部参数。</p><hr><h2 id="_8-什么是推理" tabindex="-1">8. 什么是推理？ <a class="header-anchor" href="#_8-什么是推理" aria-label="Permalink to &quot;8. 什么是推理？&quot;">​</a></h2><p>推理，英文是 inference。</p><p>简单说：</p><blockquote><p>推理就是使用训练好的模型来生成回答。</p></blockquote><p>当你在 ChatGPT、Ollama、Claude、Gemini 或其他 AI 产品里输入问题时，模型通常正在做推理。</p><p>推理流程大概是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户输入</span></span>
<span class="line"><span>→ 切成 token</span></span>
<span class="line"><span>→ 模型用参数计算</span></span>
<span class="line"><span>→ 预测下一个 token</span></span>
<span class="line"><span>→ 不断生成</span></span>
<span class="line"><span>→ 输出回答</span></span></code></pre></div><p>推理时，模型参数通常不会改变。</p><p>它只是使用已经学好的参数。</p><hr><h2 id="_9-训练-vs-推理" tabindex="-1">9. 训练 vs 推理 <a class="header-anchor" href="#_9-训练-vs-推理" aria-label="Permalink to &quot;9. 训练 vs 推理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>训练</th><th>推理</th></tr></thead><tbody><tr><td>目的</td><td>调整模型能力</td><td>使用模型能力</td></tr><tr><td>参数会不会变</td><td>会变</td><td>通常不变</td></tr><tr><td>成本</td><td>很高</td><td>相对低，但大量调用也很贵</td></tr><tr><td>数据</td><td>大量训练数据</td><td>用户输入和上下文</td></tr><tr><td>时间</td><td>可能数小时、数天、数周</td><td>通常几百毫秒到几十秒</td></tr><tr><td>类比</td><td>学生学习</td><td>学生考试答题</td></tr><tr><td>产品阶段</td><td>模型研发 / 微调</td><td>用户真实使用</td></tr></tbody></table><p>一句话记住：</p><blockquote><p>训练是在“学”，推理是在“用”。</p></blockquote><hr><h2 id="_10-什么是预训练" tabindex="-1">10. 什么是预训练？ <a class="header-anchor" href="#_10-什么是预训练" aria-label="Permalink to &quot;10. 什么是预训练？&quot;">​</a></h2><p>预训练，英文是 pretraining。</p><p>简单说：</p><blockquote><p>预训练是模型第一次大规模学习语言和世界知识的阶段。</p></blockquote><p>模型会读大量文本，例如：</p><ul><li>网页</li><li>书籍</li><li>代码</li><li>百科</li><li>论文</li><li>对话</li><li>文档</li></ul><p>它学会：</p><ul><li>语言规律</li><li>基础知识</li><li>代码结构</li><li>常见表达</li><li>推理模式</li></ul><p>预训练成本非常高。</p><p>普通团队通常不会从零预训练一个大模型。</p><p>更多时候会使用已有开源模型或闭源模型。</p><hr><h2 id="_11-什么是微调" tabindex="-1">11. 什么是微调？ <a class="header-anchor" href="#_11-什么是微调" aria-label="Permalink to &quot;11. 什么是微调？&quot;">​</a></h2><p>微调，英文是 fine-tuning。</p><p>简单说：</p><blockquote><p>微调是在已有模型基础上，用较小的数据继续训练，让它更适合某个任务或风格。</p></blockquote><p>比如一个通用模型本来什么都懂一点。</p><p>你可以用客服数据微调它，让它更像客服助手。</p><p>也可以用法律文档微调它，让它更熟悉法律表达。</p><p>也可以用代码评审数据微调它，让它更擅长 code review。</p><p>微调不是重新造一个模型。</p><p>它更像：</p><blockquote><p>给已经毕业的人做岗位培训。</p></blockquote><hr><h2 id="_12-什么是继续预训练" tabindex="-1">12. 什么是继续预训练？ <a class="header-anchor" href="#_12-什么是继续预训练" aria-label="Permalink to &quot;12. 什么是继续预训练？&quot;">​</a></h2><p>继续预训练，英文常叫 continued pretraining。</p><p>它和普通微调不完全一样。</p><p>简单理解：</p><blockquote><p>继续预训练是让模型继续阅读某个领域的大量原始文本，补充领域知识和语言习惯。</p></blockquote><p>比如你有很多医疗文档、金融报告、法律材料、代码仓库。</p><p>你可以让模型继续在这些文本上学习。</p><p>它更像：</p><blockquote><p>让模型继续读专业书。</p></blockquote><p>而 SFT 更像：</p><blockquote><p>教模型如何按指令回答问题。</p></blockquote><p>两者目标不一样。</p><hr><h2 id="_13-什么是-sft" tabindex="-1">13. 什么是 SFT？ <a class="header-anchor" href="#_13-什么是-sft" aria-label="Permalink to &quot;13. 什么是 SFT？&quot;">​</a></h2><p>SFT 是 Supervised Fine-Tuning。</p><p>中文可以叫：</p><blockquote><p>监督式微调。</p></blockquote><p>简单说：</p><blockquote><p>给模型很多“问题 → 好答案”的样本，让它学会按这种方式回答。</p></blockquote><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户：帮我写一封请假邮件</span></span>
<span class="line"><span>助手：你好，我因身体不适需要请假一天……</span></span></code></pre></div><p>SFT 让模型学会：</p><ul><li>听指令</li><li>按格式输出</li><li>使用某种语气</li><li>遵守回答规范</li><li>适配业务场景</li></ul><p>后面我们会单独讲 SFT。</p><hr><h2 id="_14-参数和知识的关系" tabindex="-1">14. 参数和知识的关系 <a class="header-anchor" href="#_14-参数和知识的关系" aria-label="Permalink to &quot;14. 参数和知识的关系&quot;">​</a></h2><p>很多初学者会问：</p><blockquote><p>模型知识是不是都存在参数里？</p></blockquote><p>粗略说，是的，模型在训练中学到的很多模式会被压缩进参数里。</p><p>但要小心理解。</p><p>参数不是一本可直接翻阅的书。</p><p>它更像：</p><blockquote><p>大量知识和语言模式被压缩进一个复杂的数字网络。</p></blockquote><p>这也是为什么模型会：</p><ul><li>知道很多常识</li><li>但不一定知道最新信息</li><li>能生成流畅回答</li><li>但有时会编造细节</li><li>记得训练中常见模式</li><li>但不可靠地记住每个事实</li></ul><p>所以如果产品需要准确使用企业知识，不能只靠参数。</p><p>通常需要 RAG、工具调用或数据库查询。</p><hr><h2 id="_15-训练数据和参数的关系" tabindex="-1">15. 训练数据和参数的关系 <a class="header-anchor" href="#_15-训练数据和参数的关系" aria-label="Permalink to &quot;15. 训练数据和参数的关系&quot;">​</a></h2><p>训练数据会影响参数。</p><p>参数会影响模型行为。</p><p>所以：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据质量 → 参数状态 → 模型输出质量</span></span></code></pre></div><p>如果训练数据里有很多错误、偏见、过期内容，模型也可能学到这些问题。</p><p>这就是为什么数据清洗很重要。</p><p>坏数据训练出来的模型，就像学生一直看错误答案。</p><hr><h2 id="_16-推理时为什么会有随机性" tabindex="-1">16. 推理时为什么会有随机性？ <a class="header-anchor" href="#_16-推理时为什么会有随机性" aria-label="Permalink to &quot;16. 推理时为什么会有随机性？&quot;">​</a></h2><p>你可能发现，同一个问题问两次，模型回答不完全一样。</p><p>这是因为推理时模型不是永远选唯一答案。</p><p>它会给下一个 token 算出很多可能性。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今天天气很好，我们去</span></span></code></pre></div><p>后面可能是：</p><ul><li>公园</li><li>散步</li><li>爬山</li><li>海边</li></ul><p>模型会根据概率选择。</p><p>有些参数设置会影响生成结果，比如：</p><ul><li>temperature</li><li>top_p</li><li>max tokens</li></ul><p>简单理解：</p><table tabindex="0"><thead><tr><th>参数</th><th>作用</th><th>类比</th></tr></thead><tbody><tr><td>temperature</td><td>控制随机程度</td><td>保守 vs 有创意</td></tr><tr><td>top_p</td><td>控制候选范围</td><td>只从高概率答案里选</td></tr><tr><td>max tokens</td><td>控制最长输出</td><td>限制回答长度</td></tr></tbody></table><p>后面讲推理优化时会更深入。</p><hr><h2 id="_17-temperature-是什么" tabindex="-1">17. Temperature 是什么？ <a class="header-anchor" href="#_17-temperature-是什么" aria-label="Permalink to &quot;17. Temperature 是什么？&quot;">​</a></h2><p>Temperature 可以理解成：</p><blockquote><p>模型回答的冒险程度。</p></blockquote><p>低 temperature：</p><ul><li>更稳定</li><li>更保守</li><li>更适合事实问答、分类、结构化输出</li></ul><p>高 temperature：</p><ul><li>更发散</li><li>更有创意</li><li>更适合脑暴、文案、故事生成</li></ul><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给我 10 个咖啡店名字</span></span></code></pre></div><p>可以用高一点的 temperature。</p><p>但：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从合同中抽取付款日期</span></span></code></pre></div><p>应该用低一点的 temperature。</p><p>产品经理要记住：</p><blockquote><p>生成参数也是产品体验的一部分。</p></blockquote><hr><h2 id="_18-为什么推理会慢" tabindex="-1">18. 为什么推理会慢？ <a class="header-anchor" href="#_18-为什么推理会慢" aria-label="Permalink to &quot;18. 为什么推理会慢？&quot;">​</a></h2><p>LLM 生成回答通常是一个 token 一个 token 地生成。</p><p>它不是一次性吐出整段话。</p><p>流程是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>预测第 1 个 token</span></span>
<span class="line"><span>→ 把第 1 个 token 加回上下文</span></span>
<span class="line"><span>→ 预测第 2 个 token</span></span>
<span class="line"><span>→ 继续</span></span></code></pre></div><p>所以输出越长，耗时越久。</p><p>影响推理速度的因素包括：</p><ul><li>模型大小</li><li>输入 token 数</li><li>输出 token 数</li><li>GPU 性能</li><li>是否使用 KV cache</li><li>是否批量推理</li><li>服务框架是否高效</li></ul><p>后面我们会讲 KV cache、vLLM、Flash Attention 等优化方法。</p><hr><h2 id="_19-为什么训练很贵" tabindex="-1">19. 为什么训练很贵？ <a class="header-anchor" href="#_19-为什么训练很贵" aria-label="Permalink to &quot;19. 为什么训练很贵？&quot;">​</a></h2><p>训练贵是因为它不只是“跑一次模型”。</p><p>训练要反复：</p><ol><li>读大量数据</li><li>前向计算</li><li>计算错误</li><li>反向传播</li><li>更新参数</li><li>重复很多轮</li></ol><p>特别是大模型，参数可能有几十亿、几百亿。</p><p>每次更新都需要大量计算和显存。</p><p>所以大多数产品团队不会从零训练大模型。</p><p>更常见的是：</p><ul><li>调用闭源模型 API</li><li>使用开源模型本地推理</li><li>做 LoRA / QLoRA 微调</li><li>做 RAG</li><li>做 prompt engineering</li></ul><hr><h2 id="_20-产品上什么时候需要训练或微调" tabindex="-1">20. 产品上什么时候需要训练或微调？ <a class="header-anchor" href="#_20-产品上什么时候需要训练或微调" aria-label="Permalink to &quot;20. 产品上什么时候需要训练或微调？&quot;">​</a></h2><p>不是所有 AI 产品都需要微调。</p><p>先问这几个问题：</p><h3 id="问题-1-prompt-能解决吗" tabindex="-1">问题 1：Prompt 能解决吗？ <a class="header-anchor" href="#问题-1-prompt-能解决吗" aria-label="Permalink to &quot;问题 1：Prompt 能解决吗？&quot;">​</a></h3><p>如果只是格式、语气、步骤不稳定，可能先优化 prompt。</p><h3 id="问题-2-rag-能解决吗" tabindex="-1">问题 2：RAG 能解决吗？ <a class="header-anchor" href="#问题-2-rag-能解决吗" aria-label="Permalink to &quot;问题 2：RAG 能解决吗？&quot;">​</a></h3><p>如果问题是模型不知道你的企业知识，通常先考虑 RAG。</p><h3 id="问题-3-工具调用能解决吗" tabindex="-1">问题 3：工具调用能解决吗？ <a class="header-anchor" href="#问题-3-工具调用能解决吗" aria-label="Permalink to &quot;问题 3：工具调用能解决吗？&quot;">​</a></h3><p>如果问题需要查订单、查库存、查账户，应该接工具或数据库。</p><h3 id="问题-4-微调真的必要吗" tabindex="-1">问题 4：微调真的必要吗？ <a class="header-anchor" href="#问题-4-微调真的必要吗" aria-label="Permalink to &quot;问题 4：微调真的必要吗？&quot;">​</a></h3><p>如果你需要模型稳定学会某种风格、格式、任务模式，才考虑微调。</p><p>一句话：</p><blockquote><p>微调不是第一个选择，通常是 prompt、RAG、工具都不够时的选择。</p></blockquote><hr><h2 id="_21-常见方案选择" tabindex="-1">21. 常见方案选择 <a class="header-anchor" href="#_21-常见方案选择" aria-label="Permalink to &quot;21. 常见方案选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题类型</th><th>优先方案</th></tr></thead><tbody><tr><td>回答格式不好</td><td>Prompt / 输出约束</td></tr><tr><td>不知道公司文档</td><td>RAG</td></tr><tr><td>需要实时订单数据</td><td>工具调用 / 数据库查询</td></tr><tr><td>语气不符合品牌</td><td>Prompt，必要时 SFT</td></tr><tr><td>特定任务长期不稳定</td><td>SFT / LoRA</td></tr><tr><td>需要领域语言习惯</td><td>Continued pretraining 或领域微调</td></tr><tr><td>推理太贵</td><td>小模型、缓存、量化、路由</td></tr><tr><td>推理太慢</td><td>模型服务优化、KV cache、批处理</td></tr></tbody></table><hr><h2 id="_22-模型参数会在用户使用时改变吗" tabindex="-1">22. 模型参数会在用户使用时改变吗？ <a class="header-anchor" href="#_22-模型参数会在用户使用时改变吗" aria-label="Permalink to &quot;22. 模型参数会在用户使用时改变吗？&quot;">​</a></h2><p>通常不会。</p><p>用户和模型对话时，模型参数一般不会因为这一段对话自动更新。</p><p>它只是把当前上下文放进模型里，然后生成回答。</p><p>如果产品想让 AI “记住用户偏好”，通常不是直接改模型参数，而是用：</p><ul><li>用户画像</li><li>记忆系统</li><li>数据库存储</li><li>RAG 检索</li><li>长期 memory</li></ul><p>所以：</p><blockquote><p>记忆系统不等于模型参数自动更新。</p></blockquote><p>这是非常重要的产品认知。</p><hr><h2 id="_23-本课总结" tabindex="-1">23. 本课总结 <a class="header-anchor" href="#_23-本课总结" aria-label="Permalink to &quot;23. 本课总结&quot;">​</a></h2><p>参数是模型内部的大量数字，决定模型如何处理输入和生成输出。</p><p>训练是调整参数。</p><p>推理是使用参数。</p><p>预训练让模型学会基础语言和知识。</p><p>微调让模型更适合特定任务或风格。</p><p>继续预训练让模型继续吸收某个领域的大量文本。</p><p>产品设计中，不要一上来就想微调，要先判断：</p><ul><li>Prompt 是否够用</li><li>RAG 是否更合适</li><li>工具调用是否必要</li><li>成本和风险是否可控</li></ul><hr><h2 id="_24-心智模型" tabindex="-1">24. 心智模型 <a class="header-anchor" href="#_24-心智模型" aria-label="Permalink to &quot;24. 心智模型&quot;">​</a></h2><p>把模型想成一个厨师。</p><ul><li>参数：厨师脑子里的经验和手感</li><li>训练：厨师练习做菜</li><li>预训练：厨师学习大量基础菜系</li><li>微调：厨师接受某家餐厅的岗位培训</li><li>推理：厨师真正给客人做菜</li><li>Prompt：顾客点菜要求</li><li>RAG：临时递给厨师的菜单和配方</li><li>工具调用：厨师去仓库查库存或找收银台查订单</li></ul><hr><h2 id="_25-初学者常见错误" tabindex="-1">25. 初学者常见错误 <a class="header-anchor" href="#_25-初学者常见错误" aria-label="Permalink to &quot;25. 初学者常见错误&quot;">​</a></h2><h3 id="错误-1-以为参数越多越好" tabindex="-1">错误 1：以为参数越多越好 <a class="header-anchor" href="#错误-1-以为参数越多越好" aria-label="Permalink to &quot;错误 1：以为参数越多越好&quot;">​</a></h3><p>不一定。</p><p>大模型更强，但也更慢、更贵、更难部署。</p><h3 id="错误-2-以为微调能解决所有问题" tabindex="-1">错误 2：以为微调能解决所有问题 <a class="header-anchor" href="#错误-2-以为微调能解决所有问题" aria-label="Permalink to &quot;错误 2：以为微调能解决所有问题&quot;">​</a></h3><p>不一定。</p><p>企业知识更新、实时数据查询、权限判断，通常更适合 RAG 或工具调用。</p><h3 id="错误-3-以为用户聊天会自动改变模型" tabindex="-1">错误 3：以为用户聊天会自动改变模型 <a class="header-anchor" href="#错误-3-以为用户聊天会自动改变模型" aria-label="Permalink to &quot;错误 3：以为用户聊天会自动改变模型&quot;">​</a></h3><p>通常不会。</p><p>对话上下文只是临时输入，不等于模型参数被更新。</p><h3 id="错误-4-混淆训练和推理" tabindex="-1">错误 4：混淆训练和推理 <a class="header-anchor" href="#错误-4-混淆训练和推理" aria-label="Permalink to &quot;错误 4：混淆训练和推理&quot;">​</a></h3><p>训练是在学，推理是在用。</p><p>两者成本、流程、目标都不同。</p><hr><h2 id="_26-小练习" tabindex="-1">26. 小练习 <a class="header-anchor" href="#_26-小练习" aria-label="Permalink to &quot;26. 小练习&quot;">​</a></h2><p>判断下面问题更适合 prompt、RAG、工具调用还是微调：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. AI 回答太啰嗦，希望变简洁。</span></span>
<span class="line"><span>2. AI 不知道公司最新退款政策。</span></span>
<span class="line"><span>3. AI 需要查询用户订单状态。</span></span>
<span class="line"><span>4. AI 总是不能按照固定客服话术回答。</span></span></code></pre></div><p>参考答案：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 → Prompt</span></span>
<span class="line"><span>2 → RAG</span></span>
<span class="line"><span>3 → 工具调用 / 数据库查询</span></span>
<span class="line"><span>4 → Prompt，必要时 SFT / LoRA 微调</span></span></code></pre></div><hr><h2 id="_27-小项目" tabindex="-1">27. 小项目 <a class="header-anchor" href="#_27-小项目" aria-label="Permalink to &quot;27. 小项目&quot;">​</a></h2><p>设计一个“模型方案选择表”。</p><p>场景：AI 客服机器人。</p><p>填写下面表格：</p><table tabindex="0"><thead><tr><th>需求</th><th>方案</th><th>原因</th></tr></thead><tbody><tr><td>回答语气要更礼貌</td><td>Prompt / SFT</td><td>Prompt 先试，不稳定再微调</td></tr><tr><td>查询订单物流</td><td>工具调用</td><td>需要实时数据</td></tr><tr><td>回答退款政策</td><td>RAG</td><td>政策会更新，适合查知识库</td></tr><tr><td>降低推理成本</td><td>小模型 / 缓存 / 路由</td><td>高频问题不一定用大模型</td></tr><tr><td>复杂投诉处理</td><td>大模型 + 人工兜底</td><td>风险高，需要 HITL</td></tr></tbody></table><p>练习目标：</p><blockquote><p>不要把所有问题都交给微调，而是学会选择合适的工程方案。</p></blockquote><hr><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p>第 6 课：开源模型 vs 闭源模型。</p><p>我们会学习：</p><blockquote><p>什么时候用 OpenAI、Claude、Gemini 这类闭源模型，什么时候用 Llama、Qwen、Mistral 这类开源模型？</p></blockquote>`,294)])])}const b=t(i,[["render",s]]);export{u as __pageData,b as default};
